def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if (r,c) in seen or g[r][c]==bg: continue
            col=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==col:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((col,cells))
    # Identify the prominent component with perpendicular straight arms.
    candidates=[]
    for col,cells in comps:
        S=set(cells)
        for r,c in cells:
            for dr in (-1,1):
                for dc in (-1,1):
                    v=0
                    while (r+dr*v,c) in S: v+=1
                    # count in each direction from elbow, including elbow
                    v2=0
                    while (r-dr*v2,c) in S: v2+=1
                    hh=0
                    while (r,c+dc*hh) in S: hh+=1
                    hh2=0
                    while (r,c-dc*hh2) in S: hh2+=1
                    # L corner has arm lengths >=3 extending on one side each
                    for vl,vd in ((v,v2),(v2,v)):
                        for hl,hd in ((hh,hh2),(hh2,hh)):
                            if vl>=3 and hl>=3:
                                # ensure the chosen two arms point one way each, and score
                                score=vl+hl+len(cells)*0.001
                                candidates.append((score,col,cells,(r,c),
                                                  (1 if (r-dr if False else 0) else 0)))
    # Easier robust elbow recovery: test each cell and sign pair; select maximal pair.
    best=None
    for col,cells in comps:
        S=set(cells)
        for r,c in cells:
            for vr in (-1,1):
                for hc in (-1,1):
                    a=0
                    while (r+vr*a,c) in S: a+=1
                    b=0
                    while (r,c+hc*b) in S: b+=1
                    if a>=3 and b>=3:
                        score=a+b+len(cells)*0.001
                        if best is None or score>best[0]: best=(score,col,cells,(r,c),vr,hc)
    if best is None: return g
    _,sigcol,sigcells,(r0,c0),vr,hc=best
    # Open quadrant is opposite the two arms.
    orow=-vr; ocol=-hc
    choices=[]
    for col,cells in comps:
        if col==sigcol and cells is sigcells: continue
        valid=[(r,c) for r,c in cells if (r-r0)*orow>0 and (c-c0)*ocol>0]
        if valid:
            d=min(abs(r-r0)+abs(c-c0) for r,c in valid)
            choices.append((d,col,cells))
    if not choices: return g
    _,target,cells=min(choices,key=lambda x:x[0])
    for r,c in cells: g[r][c]=sigcol
    return g

